const Research=(()=>{
const catalog={agriculture:[['plow','Plow','Turn soil more efficiently.'],['irrigation','Irrigation','Bring water to thirsty crops.'],['rotation','Crop rotation','Keep fields healthy between harvests.'],['storage','Food preservation','Make each harvest go further.']],industry:[['wheel','Wheel','Move heavy loads more easily.'],['mill','Watermill','Use moving water to power work.'],['tools','Standard tools','Make dependable tools for workers.'],['guild','Craft guilds','Share useful techniques between towns.']],arms:[['shield','Reinforced shields','Protect soldiers with stronger equipment.'],['bow','Improved bows','Train and equip more effective archers.'],['stirrup','Stirrups','Help mounted troops stay steady.'],['fortification','Fortification plans','Improve military engineering.']]};
function upgrade(s){s.release='0.5.0';s.countries.forEach(c=>{c.literacy=c.literacy??35;c.researchBank=c.researchBank||{agriculture:0,industry:0,arms:0};c.researchBank[c.focus]=c.progress;});return s;}
function focus(c,key){if(!catalog[key])throw Error('Choose a research field.');c.researchBank[c.focus]=c.progress;c.focus=key;c.progress=c.researchBank[key]||0;}
function achievement(key,level){const a=catalog[key]?.[level];return a?{id:a[0],name:a[1],text:a[2],bonus:key==='agriculture'?'+15% food production':key==='industry'?'+15% raw-resource production':'+10% military strength'}:null;}
function education(s,c,notes){const population=s.cells.filter(x=>x.country===c.id).reduce((n,x)=>n+x.population,0),rates={schools:[.003,.8],workshops:[.002,.5],academies:[.004,1.2]},[rate,gain]=rates[c.education],cost=population*rate,paid=Math.min(cost,c.stock.money);c.stock.money-=paid;const schools=s.cells.filter(x=>x.country===c.id&&x.buildings.includes('school')).length;c.literacy=Math.max(0,Math.min(100,c.literacy+(cost===0?0:paid/cost)*gain+Math.min(1,schools*.15)-(paid<cost?.7:0)));notes.push(`${c.name}: education cost ${paid.toFixed(1)}; learning level ${Math.round(c.literacy)}%.`);}
function finish(c,notes){const need={agriculture:40,industry:40,arms:45}[c.focus]*(c.tech[c.focus]+1);if(c.tech[c.focus]<4&&c.progress>=need){c.progress-=need;c.tech[c.focus]++;const a=achievement(c.focus,c.tech[c.focus]-1);notes.push(`${c.name} discovered ${a.name}: ${a.bonus}.`);}if(c.tech[c.focus]>=4)c.progress=0;c.researchBank[c.focus]=c.progress;}
function validate(s){for(const c of s.countries){if(!Number.isFinite(c.literacy)||c.literacy<0||c.literacy>100||!c.researchBank||Object.keys(catalog).some(k=>!Number.isFinite(c.researchBank[k])||c.researchBank[k]<0))throw Error('Invalid education or research progress.');}}
return {catalog,upgrade,focus,achievement,education,finish,validate};})();
